                      <span class="status-key ${iconClass}">${key}:</span>
                      <span class="status-value">${blockData[key]}</span>
                  </div>`;
          }
          container.innerHTML = contentHTML;
      }

      function renderSecretDiary(diaryText) {
          const contentEl = document.querySelector('.secret-diary-content');
          if (diaryText && contentEl) {
              contentEl.textContent = diaryText;
          }
      }

      const rawData = dataContainer.textContent.trim();
      if (rawData) {
          const parsedData = parseData(rawData);
          renderHeader(parsedData['页眉']);
          renderBlock('kyoko-content', parsedData['杏子']);
          renderBlock('mio-content', parsedData['澪']);
          renderSecretDiary(parsedData['秘密日记']);
      }
    });
    </script>
</body>
</html>
